.sq-lab{font-family:var(--font-body);color:#15212c;background:#f5f2ea;border:1px solid rgba(23,44,56,.12);border-radius:22px;padding:18px;box-shadow:0 20px 50px rgba(29,46,55,.1)}
.sq-lab *{box-sizing:border-box;min-width:0}.sq-lab-toolbar{position:sticky;top:10px;z-index:10;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 14px;background:rgba(255,253,247,.93);backdrop-filter:blur(14px);border:1px solid rgba(23,44,56,.1);border-radius:14px;margin-bottom:12px}.sq-lab-toolbar>div{display:flex;flex-direction:column}.sq-lab-toolbar span,.sq-surface-head>div>span{font-family:var(--font-mono);font-size:10px;letter-spacing:.08em;color:#6e7b7d}.sq-lab-toolbar strong{font-size:14px}.sq-lab-toolbar nav{display:flex;gap:5px;flex-wrap:wrap}.sq-lab-toolbar button{appearance:none;border:1px solid #d9d9d1;background:#fffdf8;color:#506064;border-radius:999px;padding:7px 11px;font:700 11px var(--font-body);cursor:pointer}.sq-lab-toolbar button.active{background:#123e4a;color:#fff;border-color:#123e4a}.sq-warning{display:grid;grid-template-columns:auto 1fr;gap:10px 14px;align-items:start;padding:13px 15px;background:#fff9e8;border:1px solid #ead9a5;border-radius:12px;margin-bottom:16px;font-size:12px;line-height:1.55}.sq-warning strong{color:#8a5d0a}.sq-warning span{color:#5d625f}.sq-surface{background:#fffdf8;border:1px solid rgba(23,44,56,.11);border-radius:18px;overflow:hidden;margin:0 0 18px;box-shadow:0 7px 22px rgba(29,46,55,.06)}.sq-surface-head{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:17px 20px;background:#fdfbf5;border-bottom:1px solid rgba(23,44,56,.09)}.sq-surface-head h2{font-size:20px;line-height:1.15;margin:2px 0 0;color:#162d37}.sq-pass{display:flex;align-items:center;gap:7px;color:#166149;background:#edf8f2;border:1px solid #cce7d9;border-radius:999px;padding:6px 10px;font:700 10px var(--font-mono);white-space:nowrap}.sq-pass i{width:7px;height:7px;border-radius:50%;background:#21865f}.sq-compare{display:grid;grid-template-columns:1fr 1fr}.sq-side{padding:18px;overflow-wrap:anywhere}.sq-side+.sq-side{border-left:1px solid rgba(23,44,56,.1)}.sq-side-template{background:#fffdfa}.sq-side-ai{background:#f2f8f7}.sq-side-label{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:13px}.sq-side-label span{font:800 11px var(--font-mono);letter-spacing:.06em;text-transform:uppercase;color:#8a5d0a}.sq-side-ai .sq-side-label span{color:#0f6570}.sq-side-label small{font-size:10px;color:#7b8586}.sq-doc{border:1px solid #e2dfd6;border-radius:13px;overflow:hidden;background:#fff}.sq-doc-title{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 15px;border-bottom:1px solid #ece8de}.sq-doc-title span{font:600 9px var(--font-mono);color:#798181}.sq-doc-title h3{font-size:15px;margin:2px 0 0}.sq-source{color:#8a5d0a!important;background:#fff6dc;padding:4px 7px;border-radius:999px}.sq-summary{padding:13px 15px;background:#f7f6f1;font-weight:700;font-size:12px;line-height:1.55}.sq-doc-section{padding:13px 15px;border-top:1px solid #ece8de}.sq-doc-section h4,.sq-weekly h4{font-size:12px;margin:0 0 8px;color:#173e49}.sq-blurb{font-size:10px;color:#788284;margin:-3px 0 9px}.sq-stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px 10px}.sq-stat{display:flex;justify-content:space-between;gap:7px;padding:5px 7px;background:#f5f4ef;border-radius:7px;font-size:10px}.sq-doc ul,.sq-weekly ul{margin:7px 0 0;padding-left:17px}.sq-doc li,.sq-weekly li{font-size:10.5px;line-height:1.5;margin:3px 0}.sq-sev-critical{color:#9e2931}.sq-sev-warning{color:#7b5608}.sq-more{font:600 9px var(--font-mono);color:#8a5d0a;margin-top:7px}.sq-empty{font-size:11px;color:#697678}.sq-empty-hero{padding:15px}.sq-narrative{padding:19px;background:#fff;border:1px solid #cfe2df;border-radius:13px;box-shadow:0 8px 20px rgba(15,101,112,.07)}.sq-narrative span{display:block;font:800 9px var(--font-mono);color:#0f6570;letter-spacing:.07em;text-transform:uppercase;margin-bottom:8px}.sq-narrative p{font-size:14px;line-height:1.65;margin:0;color:#20363c}.sq-underlay,.sq-collapsed-facts{margin-top:10px;padding:10px 12px;border:1px dashed #b9ceca;border-radius:10px;color:#5d7073;font-size:11px}.sq-underlay span{font:700 9px var(--font-mono);text-transform:uppercase}.sq-underlay p{margin:4px 0 0}.sq-no-ai{display:grid;place-items:start;min-height:170px;padding:18px;background:#fff;border:1px dashed #b9ceca;border-radius:13px}.sq-no-ai span{font:800 10px var(--font-mono);color:#0f6570;text-transform:uppercase}.sq-no-ai p{font-size:12px;color:#607174;line-height:1.6}.sq-prompt{border-top:1px solid rgba(23,44,56,.09);background:#fbfaf6}.sq-prompt summary{cursor:pointer;padding:11px 18px;font:700 10px var(--font-mono);color:#657174}.sq-prompt p{padding:0 18px 15px;margin:0;font:11px/1.65 var(--font-mono);color:#4d5d61}.sq-phone{max-width:360px;margin:0 auto;background:#111a20;color:#fff;border-radius:30px;padding:12px;border:6px solid #26333a;box-shadow:0 14px 28px rgba(17,26,32,.18)}.sq-phone-top{display:flex;justify-content:space-between;padding:1px 8px 11px;font:600 9px var(--font-mono);color:#c9d1d5}.sq-notification{display:grid;grid-template-columns:34px 1fr;gap:10px;padding:12px;background:rgba(255,255,255,.95);color:#172a33;border-radius:17px}.sq-notification-ai{background:#eff8f6}.sq-appmark{width:34px;height:34px;display:grid;place-items:center;border-radius:9px;background:#123e4a;color:#fff;font-weight:900}.sq-notification-title{font-size:11px;font-weight:800}.sq-notification p{font-size:11px;line-height:1.42;margin:4px 0}.sq-notification small{color:#718084;font-size:9px}.sq-weekly{background:#fff;border:1px solid #e2dfd6;border-radius:13px;padding:14px}.sq-weekly-head{display:flex;justify-content:space-between;gap:10px;padding-bottom:10px;border-bottom:1px solid #ece8de}.sq-weekly-head span{font-weight:800}.sq-weekly-head strong{font:700 9px var(--font-mono);color:#8a5d0a}.sq-weekly p,.sq-weekly li{font-size:11px;line-height:1.55}.sq-ai-summary{padding:13px;margin:12px 0;background:#eef7f5;border:1px solid #cfe2df;border-radius:10px}.sq-ai-summary b{font-size:11px;color:#0f6570}.sq-ai-summary p{margin:5px 0 0}.sq-prompt[open]{background:#f6f4ee}
@media(max-width:800px){.sq-compare{grid-template-columns:1fr}.sq-side+.sq-side{border-left:0;border-top:1px solid rgba(23,44,56,.1)}.sq-lab{padding:10px;border-radius:14px}.sq-lab-toolbar{position:static;align-items:flex-start;flex-direction:column}.sq-surface-head{align-items:flex-start;flex-direction:column}.sq-warning{grid-template-columns:1fr}.sq-stats{grid-template-columns:1fr}}
@media print{.sq-lab-toolbar nav,.sq-prompt{display:none}.sq-surface{break-inside:avoid}.sq-lab{box-shadow:none;background:#fff}.sq-compare{grid-template-columns:1fr 1fr}}

