document.addEventListener('click', function(event){
  const button = event.target.closest('[data-filter]');
  if(!button) return;
  const filter = button.dataset.filter;
  document.querySelectorAll('[data-filter]').forEach(function(item){ item.classList.toggle('active', item === button); });
  document.querySelectorAll('.sq-surface').forEach(function(surface){ surface.hidden = filter !== 'all' && surface.dataset.group !== filter; });
});
